from typing import List
class Solution:
    def singleNumber(self, nums: List[int]) -> int:
        seen = set()
        for x in nums:
            if x in seen:
                seen.remove(x)
            else:
                seen.add(x)
        return next(iter(seen))

code.java:
class Solution {
    public int singleNumber(int[] nums) {
        Set<Integer> seen = new HashSet<>();
        for (int x : nums) {
            if (!seen.add(x)) seen.remove(x);
        }
        return seen.iterator().next();
    }
}

